import {ADVISORY_RULE,stageAdvisoryCandidate,analyzeAdvisory,replayAdvisories} from './advisory-engine.mjs';
import {evaluateIntelligenceReplay} from './intelligence-evaluation.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function intelligenceDesk({isActive,getWorkspace,applyWorkspace,canChange,uid,today,feedback}){
  let data=null,busy=false,live=false,error='',cutoff='',selectedCase='',reviewer='',note='';
  const $=id=>document.getElementById(id);
  async function request(action,body={}){const response=await fetch(`/api/intelligence/${action}`,{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json','X-Ruthless-Request':'official-warning-v1'},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)});if(!response.ok){let value;try{value=await response.json();}catch{}throw new Error(value?.message??value?.error??'Local journal unavailable. Run node scripts/serve-research.mjs; the hosted edition is static.');}return response.json();}
  function remember(){if($('official-reviewer'))reviewer=$('official-reviewer').value;if($('official-note'))note=$('official-note').value;}
  function render(){if(!isActive()||!$('official-journal'))return;const attempts=data?.attempts??[],latest=attempts.filter(a=>a.run.status==='collected'&&a.analysis?.topicAvailable).at(-1),candidate=latest?.analysis.candidates[0],last=attempts.at(-1),cases=getWorkspace().assessments;if(!cases.some(c=>c.id===selectedCase))selectedCase=cases[0]?.id??'';
    $('official-journal').innerHTML=`<section class="panel official-panel" aria-busy="${busy}"><div class="panel-heading"><div><p class="eyebrow">PERSISTENT EVIDENCE / INDIA</p><h2>Official warning review</h2><p>Collect → preserve → compare → verify → human review.</p></div><span class="chip">${live?'LOCAL JOURNAL':'RETAINED PUBLIC OBSERVATION'}</span></div><div class="case-body"><p>Monitor changes in the official India terrorism advisory. First or unchanged text is standing context. Changed wording becomes a verification candidate; it does not establish an imminent attack.</p><div class="actions"><button id="official-connect"${busy?' disabled':''}>Connect local journal</button><button id="official-retained"${busy?' disabled':''}>Inspect retained public capture</button><button id="official-collect" class="primary"${busy||!live?' disabled':''}>Collect due official source</button><button id="official-monitor"${busy||!live?' disabled':''}>${data?.state?.enabled?'Stop scheduled collection':'Enable hourly collection'}</button></div><p role="status" class="${error?'error':'muted'}">${esc(error||'Collection and review use the local research server. The hosted edition can inspect the explicitly dated retained public capture.')}</p>
      ${data?`<div class="watch-metrics"><div><strong>${data.retainedCount??attempts.length}</strong><span>Preserved attempts at cutoff</span></div><div><strong>${attempts.flatMap(a=>a.analysis?.candidates??[]).filter(c=>c.kind==='changed_guidance').length}</strong><span>Guidance-change candidates</span></div><div><strong>${data.reviews.length}</strong><span>Retained review decisions</span></div></div><p class="muted">Source: FCDO India travel advisory · one publisher · English. Rule ${ADVISORY_RULE}. ${live?'Next eligible request: '+esc(data.state?.nextAt?new Date(data.state.nextAt).toISOString():'Now'):'Read-only capture; no collector is running here.'}</p><p>${last?.analysis?.topicAvailable===false?'<strong class="error">Latest topic extraction is unavailable; any earlier valid passage remains separately retained.</strong>':last?.run.status==='failed'?'<strong class="error">Latest attempt failed: '+esc(last.run.reason)+'. Previous successful material is retained.</strong>':esc(latest?.analysis?.coverage??'No successful source capture yet.')}</p>
      <form id="official-replay" class="osint-controls"><div><label for="official-cutoff">Known by (UTC)</label><input id="official-cutoff" type="datetime-local" step="1" value="${esc(cutoff||data.asOf.slice(0,19))}" required></div><button${busy?' disabled':''}>Replay known evidence</button><button type="button" id="official-now"${busy?' disabled':''}>Return to latest</button></form><p class="muted">Collector controls and cooldown show current service operations. Evidence and decisions use the replay cutoff. Availability uses the journal’s first observation time as well as source capture and publisher timestamps. A current page is never backdated to its earlier publication date. Replay hides later source versions and later review notes.</p>
      ${data.omittedAttempts||data.omittedReviews?`<p class="notice">Display bounded: ${data.omittedAttempts??0} older attempts and ${data.omittedReviews??0} older reviews omitted. They remain in the local journal.</p>`:''}
      ${candidate?`<article class="official-candidate"><div class="panel-heading"><h3>${esc(candidate.title)}</h3><span class="chip">${esc(candidate.priority)}</span></div><p>${esc(candidate.explanation)}</p><p><a href="${esc(candidate.sourceURL)}" target="_blank" rel="noopener noreferrer">Original official source</a> · First observed ${esc(latest.firstObservedAt)}<br>Publisher update ${esc(candidate.publisherUpdatedAt)} · Captured ${esc(candidate.capturedAt)}</p><details><summary>Inspect exact retained passage and changes</summary><blockquote class="osint-original">${esc(candidate.excerpt)}</blockquote><p class="muted">Plain text parsed from retained source HTML; raw section offsets and hashes are in the evidence record. ${esc(candidate.confidence)}.</p>${candidate.added.length?`<h4>Added / changed paragraphs</h4>${candidate.added.map(x=>`<p>${esc(x)}</p>`).join('')}`:''}${candidate.removed.length?`<h4>Absent from current text — not confirmed resolved</h4>${candidate.removed.map(x=>`<p>${esc(x)}</p>`).join('')}`:''}</details><h4>Lawful verification questions</h4><ul>${candidate.verificationQuestions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Independent corroboration: unavailable. Contradictions: no independent source assessed. ${candidate.possibleAlternatives.map(esc).join(' ')}</p>
      <div class="osint-controls"><div><label for="official-case">Stage into existing assessment</label><select id="official-case">${cases.map(c=>`<option value="${esc(c.id)}"${c.id===selectedCase?' selected':''}>${esc(c.title)}</option>`).join('')}</select></div></div><label class="checkline"><input id="official-stage-ack" type="checkbox"${busy?' disabled':''}><span>I reviewed this passage and its time meaning. Staging it does not approve its claims.</span></label><button id="official-stage"${busy?' disabled':''}>Stage retained passage for review</button>
      <form id="official-review-form"><h4>Append human review</h4><label for="official-reviewer">Reviewer label (local, unauthenticated)</label><input id="official-reviewer" maxlength="100" value="${esc(reviewer)}" required><label for="official-disposition">Disposition</label><select id="official-disposition"><option>Needs verification</option><option>Context only</option><option>Reviewed warning</option><option>Dismissed</option></select><label for="official-note">Evidence and uncertainty note</label><textarea id="official-note" minlength="10" maxlength="2000" rows="3" required>${esc(note)}</textarea><button${busy||!live||!!cutoff?' disabled':''}>Retain review decision</button><p class="muted">Requires the latest source version and journal revision. Decisions remain separate from machine text and do not send alerts or accept workspace evidence.</p></form></article>`:'<p class="empty">No eligible terrorism passage at this cutoff. Missing coverage does not establish safety.</p>'}
      <details><summary>Observation timeline and human decisions</summary><ol>${attempts.map(a=>`<li>${esc(a.firstObservedAt)} · ${esc(a.run.status)} · ${esc(a.analysis?.candidates[0]?.kind??a.run.reason??a.analysis?.coverage??'No topic observation')}</li>`).join('')}</ol><ol>${data.reviews.map(r=>`<li>${esc(r.at)} · ${esc(r.reviewer)} · ${esc(r.disposition)}<p>${esc(r.note)}</p></li>`).join('')}</ol></details>
      <section class="notice"><h3>Historical evaluation status</h3><p>${esc(data.evaluation?.reason??'No independently labeled historical periods have been supplied.')}</p><p>Attack precision, recall, missed incidents, false-alert rate, predictive calibration and event lead time: <strong>not estimated</strong>. ${esc(data.evaluation?.sampleSizes?.eligibleObservations??attempts.filter(a=>a.analysis?.topicAvailable).length)} eligible retained observations do not establish predictive performance.</p><p>The evaluation module compares guidance-change review with an any-page-change baseline only when complete, independently reviewed monitoring intervals are supplied.</p></section><details><summary>Traceable public evidence record</summary><p>${esc(data.operationalMetadataBasis??'')}. ${esc(data.security??'Retained public data; no signed or independently authenticated evidence claim.')}</p><textarea aria-label="Official journal evidence JSON" rows="10" readonly>${esc(JSON.stringify(data,null,2))}</textarea></details>`:'<p class="empty">No journal loaded. Connect the local service or inspect the dated real public capture.</p>'}
    </div></section>`;
  }
  async function retained(){const r=await fetch('./examples/official-advisory-observation.json',{credentials:'omit',cache:'no-store'});if(!r.ok)throw new Error('No retained public observation is packaged in this release.');const text=await r.text();if(text.length>2000000)throw new Error('Retained observation exceeds recovery bound.');const value=JSON.parse(text);if(value.format!=='ruthless-official-journal'||value.version!==1||!Array.isArray(value.attempts)||value.attempts.length>48||value.reviews?.length!==0)throw new Error('Invalid retained public journal.');for(const a of value.attempts){const analysis=await analyzeAdvisory(a.run,null);if(analysis?.topicHash!==a.analysis?.topicHash||!Number.isFinite(Date.parse(a.firstObservedAt))||Date.parse(a.firstObservedAt)<Date.parse(a.run.checkedAt))throw new Error('Retained source binding failed.');a.analysis=analysis;}return value;}
  document.addEventListener('click',async e=>{if(!isActive()||busy)return;const id=e.target.closest('button')?.id;if(!['official-connect','official-retained','official-collect','official-monitor','official-now','official-stage'].includes(id))return;remember();if(id==='official-stage'){if(!canChange())return;const a=data.attempts.filter(a=>a.analysis?.candidates?.length).at(-1);try{applyWorkspace(await stageAdvisoryCandidate(getWorkspace(),a,a.analysis.candidates[0].id,{assessmentId:selectedCase,id:uid('doc'),at:today(),acknowledged:$('official-stage-ack').checked}));feedback('Official passage staged in Document intake. Review and save the workspace separately.');}catch(err){error=err.message;}render();return;}
    busy=true;error='';render();try{if(id==='official-retained'||id==='official-now'&&!live){data=await retained();live=false;cutoff='';}else{data=await request(id==='official-collect'?'collect':id==='official-monitor'?'schedule':'query',id==='official-monitor'?{enabled:!data?.state.enabled}:{});live=true;cutoff='';}}catch(err){error=err.message;}finally{busy=false;render();}});
  document.addEventListener('input',e=>{if(e.target.id==='official-note')note=e.target.value;if(e.target.id==='official-reviewer')reviewer=e.target.value;});
  document.addEventListener('change',e=>{if(e.target.id==='official-case')selectedCase=e.target.value;});
  document.addEventListener('submit',async e=>{if(!isActive()||!['official-replay','official-review-form'].includes(e.target.id))return;e.preventDefault();if(busy)return;remember();busy=true;error='';try{if(e.target.id==='official-replay'){const value=$('official-cutoff').value,asOf=new Date(value+'Z').toISOString();if(live)data=await request('query',{asOf});else{if(Date.parse(asOf)>Date.now())throw new Error('Replay cutoff cannot be in the future.');const base=await retained(),attempts=replayAdvisories(base.attempts,asOf),first=attempts[0]?.firstObservedAt??asOf;data={...base,asOf,attempts,reviews:[],retainedCount:attempts.length,evaluation:evaluateIntelligenceReplay(attempts,{developmentEnd:new Date(Date.parse(first)-1).toISOString(),evaluationStart:first,evaluationEnd:asOf,labels:[],independentLabels:false})};}cutoff=value;}else{const a=data.attempts.filter(a=>a.analysis?.candidates?.length).at(-1);data=await request('review',{attemptId:a.id,candidateId:a.analysis.candidates[0].id,disposition:$('official-disposition').value,note,reviewer,expectedHead:data.head});note='';}}catch(err){error=err.message;}finally{busy=false;render();}});
  return {render,isBusy:()=>busy,hasDraft:()=>!!($('official-note')?$('official-note').value.trim():note.trim())};
}
